import { useEffect, useState } from "react";
import axios from "axios";

export default function Dashboard() {
  const [courses, setCourses] = useState([]);
  const [submissions, setSubmissions] = useState([]);

  useEffect(() => {
    fetchData();
  }, []);

  const fetchData = async () => {
    try {
      const courseRes = await axios.get("/api/teachers/1/courses");
      const subRes = await axios.get("/api/teachers/1/submissions");

      setCourses(courseRes.data);
      setSubmissions(subRes.data);
    } catch (err) {
      console.log(err);
    }
  };

  return (
    <div className="p-6">
      {/* SAME HEADER STYLE */}
      <h1 className="text-2xl font-bold mb-6">
        Teacher Dashboard
      </h1>

      {/* SAME SIMPLE STATS (no fancy cards) */}
      <div className="text-sm text-gray-700 mb-6">
        👨‍🏫 Courses: {courses.length} <br />
        👨‍🎓 Students:{" "}
        {courses.reduce((sum, c) => sum + (c.student_count || 0), 0)} <br />
        📥 Submissions: {submissions.length}
      </div>

      {/* SAME COURSE BOX STYLE */}
      <h2 className="text-xl font-semibold mb-3">
        My Courses
      </h2>

      {courses.map((course) => (
        <div
          key={course.course_id}
          className="bg-white p-5 rounded-lg shadow mb-5 border"
        >
          <h2 className="text-xl font-semibold mb-2">
            {course.course_name}
          </h2>

          <p className="text-sm text-gray-600">
            Code: {course.course_code}
          </p>

          <p className="text-sm text-gray-600">
            Duration: {course.duration_weeks} weeks
          </p>

          <p className="text-sm mb-2">
            Difficulty: {course.difficulty_level}
          </p>

          <div className="text-sm text-gray-700">
            👨‍🎓 Students: {course.student_count} <br />
            📝 Assignments: {course.assignment_count} <br />
            ❓ Quizzes: {course.quiz_count}
          </div>
        </div>
      ))}

      {/* SAME BOX STYLE FOR SUBMISSIONS */}
      <h2 className="text-xl font-semibold mb-3">
        Recent Submissions
      </h2>

      {submissions.length === 0 ? (
        <p className="text-gray-500">No submissions yet</p>
      ) : (
        submissions.slice(0, 5).map((s) => (
          <div
            key={s.submission_id}
            className="bg-white p-5 rounded-lg shadow mb-5 border"
          >
            <h2 className="text-lg font-semibold">
              {s.student_name}
            </h2>

            <p className="text-sm text-gray-600">
              {s.assignment_title}
            </p>

            <p className="text-sm text-gray-500">
              {new Date(s.submitted_at).toLocaleString()}
            </p>
          </div>
        ))
      )}
    </div>
  );
}
